#!/usr/bin/env node
/**
 * tests/adversarial-gtv-m3-challenger2.js
 * 
 * Milestone 3 Empirical Adversarial Challenge Suite (Challenger 2)
 * Scope: Focus System & Spatial Navigation Alignment (R3)
 * 
 * Dimensions Tested:
 * 1. Shelf auto-scrolling across .strip and .shelf-rail containers:
 *    - Edge index 0 reset (scrollLeft -> 0)
 *    - Extreme right index (index 50+, index 100)
 *    - Boundary clamping: scrollWidth - clientWidth invariance
 *    - Rapid back-and-forth traversal ('auto' vs 'smooth' throttling)
 *    - Containers with .strip alone, .shelf-rail alone, and dual .strip.shelf-rail
 * 
 * 2. Modal dialog focus trapping (.modal-dialog, .details-action-bar, .player-modal-card):
 *    - Focus perimeter encirclement (cannot escape to header or background shelves)
 *    - Programmatic setFocus() rejection for non-trapped targets
 *    - Nested trap stacking and untrap restoration
 *    - Modal dismissal focus restoration to original trigger
 * 
 * 3. Focus multi-class synchronization (focus, focused, tv-focused):
 *    - Tri-class synchronization on setFocus (all 3 present)
 *    - Tri-class cleanup on blur / navigation (all 3 removed)
 *    - Stray class sanitation across DOM (rogue elements cleaned)
 *    - Route change / view switch zero-stray guarantee
 *    - clearFocus() multi-class purge
 * 
 * 4. Zero DOM Sinks in app/js/navigation.js:
 *    - AST / regex audit for innerHTML, outerHTML, document.write, eval, new Function
 * 
 * 5. Fuzzing & Chaos Stress:
 *    - 100-key chaotic rapid directional burst
 *    - Detached element recovery (DOM removal self-healing)
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// 2. Terminal Styling
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failures = [];

function check(category, testName, fn) {
  totalChecks++;
  const idStr = totalChecks.toString().padStart(2, '0');
  process.stdout.write(`  [CHALLENGE-${idStr}] [${category}] ${testName} ... `);
  try {
    fn();
    passedChecks++;
    console.log(`${C.green}${C.bold}✔ PASS${C.reset}`);
  } catch (err) {
    failedChecks++;
    failures.push({ id: totalChecks, category, name: testName, error: err.message, stack: err.stack });
    console.log(`${C.red}${C.bold}✖ FAIL${C.reset}`);
    console.log(`      ${C.red}Defect: ${err.message}${C.reset}`);
  }
}

// 3. Mock Setup
function installScrollMocks(window) {
  window.Element.prototype.scrollIntoView = function (options) {
    this._lastScrollIntoView = options || true;
  };

  window.Element.prototype.scrollTo = function (x, y) {
    if (typeof x === 'object') {
      this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
      this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
      this._lastScrollBehavior = x.behavior || 'auto';
    } else {
      this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
      this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
    }
  };
}

function setupLayoutMock(window) {
  function makeRect(left, top, width, height) {
    return {
      left: left,
      top: top,
      width: width,
      height: height,
      right: left + width,
      bottom: top + height,
      x: left,
      y: top
    };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    var mockAttr = this.getAttribute('data-mock-rect');
    if (mockAttr) {
      try {
        var parsed = JSON.parse(mockAttr);
        return makeRect(parsed.left || 0, parsed.top || 0, parsed.width || 0, parsed.height || 0);
      } catch (e) {}
    }

    var view = this.closest('.view');
    if (view && !view.classList.contains('active')) {
      return makeRect(0, 0, 0, 0);
    }
    if (this.style.display === 'none') {
      return makeRect(0, 0, 0, 0);
    }

    // Default card in shelf: 352x198 card layout
    if (this.classList.contains('card') || this.classList.contains('card-poster')) {
      var p = this.parentElement;
      var idx = parseInt(this.getAttribute('data-nav-index'), 10);
      if (isNaN(idx) && p) {
        idx = Array.from(p.children).indexOf(this);
      }
      var sLeft = p && p.scrollLeft !== undefined ? p.scrollLeft : 0;
      var leftCoord = 96 + idx * 378 - sLeft;
      return makeRect(leftCoord, 400, 352, 198);
    }

    // Default button in modal
    if (this.classList.contains('modal-btn') || this.classList.contains('action-pill')) {
      var bIdx = parseInt(this.getAttribute('data-nav-index') || '0', 10);
      return makeRect(800 + bIdx * 140, 500, 120, 50);
    }

    return makeRect(96, 100, 100, 40);
  };
}

function createHarness(route = 'home') {
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const navPath = path.resolve(__dirname, '../app/js/navigation.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + route,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  window.__TEST_M3__ = true;
  installScrollMocks(window);
  setupLayoutMock(window);

  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  window.CinejoyApp.init();

  return { window, dom, nav: window.SpatialNav, app: window.CinejoyApp };
}

console.log(`${C.bold}${C.cyan}========================================================================${C.reset}`);
console.log(`${C.bold}${C.cyan}   MILESTONE 3 EMPIRICAL ADVERSARIAL CHALLENGE SUITE (CHALLENGER 2)     ${C.reset}`);
console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

// =============================================================================
// CATEGORY 1: Shelf Auto-Scrolling across .strip and .shelf-rail Containers
// =============================================================================
console.log(`${C.bold}${C.yellow}▶ CATEGORY 1: Shelf Auto-Scrolling across .strip and .shelf-rail at Edge Indices${C.reset}`);

check('ShelfScroll', 'Container with .strip alone scrolls on clipped card (>1824px)', () => {
