check('ModalTrap', 'Focus is strictly enclosed within .modal-dialog; cannot leak to header or background shelves', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');

  // Background shelf cards
  const shelf = window.document.createElement('div');
  shelf.className = 'content-shelf';
  const bgCard = window.document.createElement('div');
  bgCard.className = 'card f';
  bgCard.id = 'bg-card-1';
  bgCard.setAttribute('data-nav', 'true');
  bgCard.setAttribute('data-mock-rect', JSON.stringify({ left: 96, top: 400, width: 352, height: 198 }));
  shelf.appendChild(bgCard);
  activeView.appendChild(shelf);

  // Header tab
  const headerTab = window.document.querySelector('.nav-pill-item, .tab.f');

  // Modal Dialog
  const modal = window.document.createElement('div');
  modal.className = 'modal-dialog';
  modal.setAttribute('role', 'dialog');
  modal.setAttribute('aria-modal', 'true');
  activeView.appendChild(modal);

  const actionBar = window.document.createElement('div');
  actionBar.className = 'details-action-bar';
  modal.appendChild(actionBar);

  const btnPlay = window.document.createElement('button');
  btnPlay.id = 'modal-play-btn';
  btnPlay.className = 'action-pill modal-btn f';
  btnPlay.setAttribute('data-nav', 'true');
  btnPlay.setAttribute('data-nav-index', '0');
  btnPlay.setAttribute('data-mock-rect', JSON.stringify({ left: 800, top: 500, width: 120, height: 50 }));
  actionBar.appendChild(btnPlay);

  const btnTrailer = window.document.createElement('button');
  btnTrailer.id = 'modal-trailer-btn';
  btnTrailer.className = 'action-pill modal-btn f';
  btnTrailer.setAttribute('data-nav', 'true');
  btnTrailer.setAttribute('data-nav-index', '1');
  btnTrailer.setAttribute('data-mock-rect', JSON.stringify({ left: 940, top: 500, width: 120, height: 50 }));
  actionBar.appendChild(btnTrailer);

  // Set focus on trigger card before trapping
  nav.setFocus(bgCard);

  // Activate trap
  const trapped = nav.trap(modal, { triggerElement: bgCard });
  assert.strictEqual(trapped, true);
  assert.strictEqual(nav.isTrapped(), true);

  // Focus first button inside modal
  nav.setFocus(btnPlay);
  assert.strictEqual(nav.getCurrentFocus(), btnPlay);

  // Verify getCandidates returns ONLY elements inside modal
  const cands = nav.getCandidates();
  assert.strictEqual(cands.length, 2);
  assert(cands.includes(btnPlay));
  assert(cands.includes(btnTrailer));
  assert(!cands.includes(bgCard), 'Background shelf card must NOT be in candidates');
  if (headerTab) {
    assert(!cands.includes(headerTab), 'Header tab must NOT be in candidates');
  }

  // Directional navigation within modal
  nav.resetThrottle();
  const nextBtn = nav.move('right');
  assert.strictEqual(nextBtn, btnTrailer);

  // Boundary escape tests: Moving right from last modal element hits deadend
  nav.resetThrottle();
  const escapeRight = nav.move('right');
  assert.strictEqual(escapeRight, null, 'Must deadend at modal right boundary');
  assert.strictEqual(nav.getCurrentFocus(), btnTrailer);

  // Moving up cannot escape to header
  nav.resetThrottle();
  const escapeUp = nav.move('up');
  assert.strictEqual(escapeUp, null, 'Must deadend at modal top boundary, cannot escape to header');
  assert.strictEqual(nav.getCurrentFocus(), btnTrailer);

  // Moving down cannot escape to background shelves
  nav.resetThrottle();
  const escapeDown = nav.move('down');
  assert.strictEqual(escapeDown, null, 'Must deadend at modal bottom boundary, cannot escape to shelves');
  assert.strictEqual(nav.getCurrentFocus(), btnTrailer);
});

