  pBtn.setAttribute('data-nav', 'true');
  pBtn.setAttribute('data-mock-rect', JSON.stringify({ left: 800, top: 500, width: 120, height: 50 }));
  parentModal.appendChild(pBtn);

  const childModal = window.document.createElement('div');
  childModal.className = 'modal-dialog';
  activeView.appendChild(childModal);

  const cBtn = window.document.createElement('button');
  cBtn.className = 'f';
  cBtn.setAttribute('data-nav', 'true');
