  assert.strictEqual(nav.getCandidates().length, 1);
  assert.strictEqual(nav.getCandidates()[0], pBtn);

  // Push nested child trap
  nav.trap(childModal, { nested: true, triggerElement: pBtn });
  nav.setFocus(cBtn);
