// =============================================================================
// CATEGORY 6: Vertical Spatial Continuity (Header <-> Hero <-> Shelves)
// =============================================================================
console.log(`\n${C.bold}${C.yellow}▶ CATEGORY 6: Vertical Spatial Continuity (Header <-> Hero <-> Shelves)${C.reset}`);

check('VerticalContinuity', 'ArrowDown from Header Tab lands on #heroBtn / #hero-play-btn', () => {
  const { window, nav } = createHarness();
  const headerTab = window.document.querySelector('#top .tab.f, .nav-pill-item');
  const heroBtn = window.document.querySelector('#heroBtn, #hero-play-btn');

  assert(headerTab, 'Header tab must exist in DOM');
  assert(heroBtn, 'Hero button must exist in DOM');

  nav.setFocus(headerTab);
  assert.strictEqual(nav.getCurrentFocus(), headerTab);

  nav.resetThrottle();
  const moved = nav.move('down');
  assert(moved === heroBtn || (moved && (moved.id === 'heroBtn' || moved.id === 'hero-play-btn' || moved.classList.contains('hero-play-btn'))),
    `Moving down from header must land on hero button, got ${moved ? moved.id || moved.className : 'null'}`);
});

check('VerticalContinuity', 'ArrowUp from Hero Play Button returns to active Header Tab', () => {
  const { window, nav } = createHarness();
  const headerTab = window.document.querySelector('#top .tab.active, .nav-pill-item.active') ||
                    window.document.querySelector('#top .tab.f, .nav-pill-item');
  const heroBtn = window.document.querySelector('#heroBtn, #hero-play-btn');

  nav.setFocus(heroBtn);
  assert.strictEqual(nav.getCurrentFocus(), heroBtn);

  nav.resetThrottle();
  const moved = nav.move('up');
  assert(moved === headerTab || (moved && (moved.closest('#top') || moved.closest('.app-header'))),
    `Moving up from hero button must return to header, got ${moved ? moved.id || moved.className : 'null'}`);
});

check('VerticalContinuity', 'ArrowDown from Hero Play Button lands on first card of first shelf', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');
  const heroBtn = window.document.querySelector('#heroBtn, #hero-play-btn');

  // Ensure first shelf exists with a card
  let rows = activeView.querySelector('#rows');
  if (!rows) {
    rows = window.document.createElement('div');
    rows.id = 'rows';
    activeView.appendChild(rows);
  }
  const strip = window.document.createElement('div');
  strip.className = 'strip shelf-rail';
  rows.appendChild(strip);

  const firstCard = window.document.createElement('div');
  firstCard.id = 'first-shelf-card-0';
  firstCard.className = 'card f';
  firstCard.setAttribute('data-nav', 'true');
  firstCard.setAttribute('data-mock-rect', JSON.stringify({ left: 96, top: 700, width: 352, height: 198 }));
  strip.appendChild(firstCard);

  nav.setFocus(heroBtn);
  assert.strictEqual(nav.getCurrentFocus(), heroBtn);

  nav.resetThrottle();
  const moved = nav.move('down');
  assert(moved !== null, 'Must move down to shelf card');
  assert(moved.classList.contains('card') || moved.classList.contains('card-poster'),
    `Must land on shelf card, got ${moved.id || moved.className}`);
});

check('VerticalContinuity', 'ArrowUp from first shelf card falls back to Hero Play Button', () => {
  const { window, nav } = createHarness();
  const activeView = window.document.querySelector('.view.active');
  const heroBtn = window.document.querySelector('#heroBtn, #hero-play-btn');

  let rows = activeView.querySelector('#rows');
  if (!rows) {
    rows = window.document.createElement('div');
    rows.id = 'rows';
    activeView.appendChild(rows);
  }
  let strip = rows.querySelector('.strip');
  if (!strip) {
    strip = window.document.createElement('div');
    strip.className = 'strip shelf-rail';
    rows.appendChild(strip);
  }

  const card = window.document.createElement('div');
  card.className = 'card f';
  card.setAttribute('data-nav', 'true');
  card.setAttribute('data-mock-rect', JSON.stringify({ left: 96, top: 700, width: 352, height: 198 }));
  strip.appendChild(card);

  nav.setFocus(card);
  assert.strictEqual(nav.getCurrentFocus(), card);

  nav.resetThrottle();
  const moved = nav.move('up');
  assert(moved === heroBtn || (moved && (moved.id === 'heroBtn' || moved.id === 'hero-play-btn')),
    `Upward move from first shelf must land on hero button, got ${moved ? moved.id : 'null'}`);
});

// =============================================================================
